namespace IO {
    struct Stream { int id; };
    void Open(Stream& s) { s.id = 1; }
}

// 1. Explicit Scope Resolution
IO::Stream output_s;
IO::Open(output_s);

// 2. Using Declaration (single symbol)
using IO::Open;
Open(output_s); // Direct access

// 3. Using Directive (full namespace access)
using namespace IO;
Stream input_s;
Open(input_s);
